// WF-3b "Can send now?" (Code node, Run Once for All Items) — scheduled path only.
// Sends at most one email per run, only inside the send window (Config timezone) and while today's sent count
// is under daily_max. Normally that is the oldest bulk-approved ("scheduled") email. Daily minimum (Autopilot
// only): when nothing is scheduled and fewer than daily_min went out today, it sends a draft still waiting for
// review instead. Emails approved one by one in the dashboard skip this and go out immediately.

const cfg = $('Settings').first().json
// STOP ALL (dashboard banner, Settings, or an emailed "STOP ALL"): nothing scheduled goes out until resumed.
if (cfg.paused === true) return []
const tz = cfg.timezone || 'UTC'
const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: 'numeric', hourCycle: 'h23', weekday: 'short' })
    .formatToParts(new Date())
    .map(p => [p.type, p.value]),
)
const hour = Number(parts.hour)
const weekend = parts.weekday === 'Sat' || parts.weekday === 'Sun'
if (weekend && !(cfg.send_on_weekends === true || String(cfg.send_on_weekends) === 'true')) return []
if (hour < Number(cfg.send_window_start ?? 9) || hour >= Number(cfg.send_window_end ?? 18)) return []

const sentToday = $('Sent today').all().filter(i => i.json && i.json.id).length
if (sentToday >= (Number(cfg.daily_max) || 20)) return []

const next = $('Next scheduled').all().map(i => i.json).find(r => r && r.id)
if (next) return [{ json: { id: next.id, from_status: 'scheduled' } }]

if (cfg.autopilot_mode !== 'auto' || sentToday >= (Number(cfg.daily_min) || 0)) return []
const BLOCKED = ['unsubscribed', 'bounced', 'dead', 'replied']
const review = $('Review drafts').all().map(i => i.json)
  .filter(r => r && r.id && r.leads && r.leads.email && !BLOCKED.includes(r.leads.status))
  .sort((a, b) => (Number(b.leads.ai_score) || 0) - (Number(a.leads.ai_score) || 0))
if (!review.length) return []
// Best score first, but rotate every 10 minutes so one draft Gmail keeps rejecting can't block the rest.
const pick = review[Math.floor(Date.now() / 600000) % Math.min(review.length, 3)]
return [{ json: { id: pick.id, from_status: 'pending_review' } }]

// WF-3b "Target" (Code node, Run Once for All Items).
// The one email to send: from the dashboard webhook, or the row just claimed by the scheduler.
const hook = $('Dashboard: Approve & send')
const id = hook.isExecuted ? hook.first().json.body?.outreach_id : $input.all().map(i => i.json).find(r => r && r.id)?.id
return id ? [{ json: { outreach_id: id } }] : []

// WF-3b "Send result" (Code node, Run Once for Each Item).
// Normalises the output of either Gmail node (new email or reply in thread).
const r = $json || {}
return {
  json: {
    ok: !!r.id && !r.error,
    message_id: r.id || null,
    thread_id: r.threadId || null,
    error: r.error ? String(r.error.message || r.error).slice(0, 300) : null,
  },
}

// "Settings" (Code node, Run Once for All Items).
// Starts from this workflow's Config node, then applies what you saved on the dashboard's Settings page
// (Supabase row settings.key = 'outreach'). Anything missing or invalid keeps the Config value.
const cfg = { ...$('Config').first().json }
const row = $input.first().json || {}
const saved = row.value && typeof row.value === 'object' && !Array.isArray(row.value) ? row.value : {}
const MAP = {"from_name":"sender_name","daily_max":"daily_max","send_window_start":"send_window_start","send_window_end":"send_window_end","send_on_weekends":"send_on_weekends","timezone":"timezone","paused":"paused","autopilot_mode":"autopilot_mode","daily_min":"daily_min"} // dashboard key -> Config key (filled in per workflow by build.mjs)

const num = (min, max) => v => {
  const n = Number(v)
  return v !== '' && Number.isFinite(n) && n >= min && n <= max ? Math.round(n) : undefined
}
const bool = v => (typeof v === 'boolean' ? v : undefined)
const text = v => (typeof v === 'string' && v.trim() ? v.trim().slice(0, 120) : undefined)
const RULES = {
  min_score: num(0, 100),
  drafts_per_run: num(1, 50),
  daily_max: num(1, 500),
  daily_min: num(0, 500),
  send_window_start: num(0, 23),
  send_window_end: num(1, 24),
  send_on_weekends: bool,
  draft_dms: bool,
  // [] = no follow-ups ('0' is skipped by the planner); otherwise "4,7"
  follow_up_days: v => {
    const list = (Array.isArray(v) ? v : String(v).split(',')).map(Number).filter(n => Number.isInteger(n) && n > 0 && n <= 90)
    return list.length ? list.join(',') : '0'
  },
  timezone: v => {
    try {
      new Intl.DateTimeFormat('en-US', { timeZone: String(v) })
      return String(v)
    } catch {
      return undefined
    }
  },
  sign_off: text,
  signature_name: text,
  company_name: text,
  website: text,
  from_name: text,
  paused: bool,
  autopilot_mode: v => (['manual', 'digest', 'auto'].includes(v) ? v : undefined),
  auto_min_score: num(50, 100),
  digest_hour: num(0, 23),
  owner_email: v => (typeof v === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()) ? v.trim().toLowerCase() : undefined),
}

const applied = []
for (const [from, to] of Object.entries(MAP)) {
  if (saved[from] === undefined || saved[from] === null || !RULES[from]) continue
  const value = RULES[from](saved[from])
  if (value === undefined) continue
  cfg[to] = value
  applied.push(from)
}
if (cfg.send_window_start !== undefined && Number(cfg.send_window_start) >= Number(cfg.send_window_end)) {
  const base = $('Config').first().json
  cfg.send_window_start = base.send_window_start
  cfg.send_window_end = base.send_window_end
}
cfg.settings_applied = applied
return [{ json: cfg }]
